<template>
    <div>
        <div class="card mb-3"><div class="card-body row g-2 align-items-end"><div class="col-md-4"><label class="form-label">From</label><input v-model="from" type="date" class="form-control"></div><div class="col-md-4"><label class="form-label">To</label><input v-model="to" type="date" class="form-control"></div><div class="col-md-4"><button class="btn btn-success w-100" :disabled="loading" @click="load">Generate report</button></div></div></div>
        <div class="row g-3 mb-3"><div class="col-md-3"><div class="card"><div class="card-body"><div class="small text-muted">Revenue</div><div class="fs-4 fw-bold">{{ money(totals.revenue) }}</div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><div class="small text-muted">Cost of goods sold</div><div class="fs-4 fw-bold">{{ money(totals.cost) }}</div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><div class="small text-muted">Gross profit</div><div class="fs-4 fw-bold text-success">{{ money(totals.gross_profit) }}</div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><div class="small text-muted">Base units sold</div><div class="fs-4 fw-bold">{{ totals.units }}</div></div></div></div></div>
        <div class="card"><div class="card-header fw-semibold">Profit by medicine batch</div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Medicine</th><th>Batch</th><th>Expiry</th><th class="text-end">Units</th><th class="text-end">Revenue</th><th class="text-end">Cost</th><th class="text-end">Gross profit</th></tr></thead><tbody><tr v-for="r in rows" :key="`${r.medicine_batch_id}-${r.medicine_id}`"><td class="fw-semibold">{{ r.medicine_name }}</td><td>{{ r.batch_no || '—' }}</td><td>{{ r.expiry_date || '—' }}</td><td class="text-end">{{ r.sold_base_units }}</td><td class="text-end">{{ money(r.revenue) }}</td><td class="text-end">{{ money(r.cost) }}</td><td class="text-end fw-semibold" :class="r.gross_profit >= 0 ? 'text-success' : 'text-danger'">{{ money(r.gross_profit) }}</td></tr><tr v-if="!rows.length"><td colspan="7" class="text-center text-muted py-4">No sales found for this period.</td></tr></tbody></table></div></div>
        <div class="small text-muted mt-2">Profit is calculated from the cost and selling-price snapshots saved on each sale line. This is gross product profit before rent, salaries, utilities and other operating expenses.</div>
    </div>
</template>
<script setup>
import { onMounted, ref } from 'vue';import api from '../../api';import { money } from '../../utils/format';
const from=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10)),to=ref(new Date().toISOString().slice(0,10)),rows=ref([]),totals=ref({revenue:0,cost:0,gross_profit:0,units:0}),loading=ref(false);
async function load(){loading.value=true;try{const {data}=await api.get('/reports/batch-profitability',{params:{from:from.value,to:to.value}});rows.value=data.data;totals.value=data.totals;}finally{loading.value=false;}}onMounted(load);
</script>
